async function mockFetch(path) {
  if (path !== "/products.json") throw new Error("مسار غير مدعوم في المثال");
  return { status: 200, ok: true, json: async () => JSON.parse('{"items":[{"name":"دفتر","category":"قرطاسية"}]}') };
}

readNames(mockFetch).then(names => console.log(names.join("، ")));

async function classify(request) {
  let response;
  try {
    response = await request("/products.json");
  } catch {
    return "network";
  }
  if (!response.ok) return "http:" + response.status;

  try {
    const body = await response.json();
    if (!Array.isArray(body?.items)) return "data";
    return "ok:" + body.items.length;
  } catch {
    return "data";
  }
}

async function run() {
  console.log(await classify(async () => { throw new Error("offline"); }));
  console.log(await classify(async () => ({ ok: false, status: 503 })));
  console.log(await classify(async () => ({ ok: true, json: async () => JSON.parse("broken") })));
}
run();

