async function loadCatalogue(request) {
  let response;
  try {
    response = await request("/products.json");
  } catch {
    return { error: "تعذر الاتصال بالخادم.", items: [] };
  }
  if (!response.ok) {
    return { error: "خطأ HTTP (" + response.status + ").", items: [] };
  }
  try {
    const body = await response.json();
    if (!Array.isArray(body?.items) || !body.items.every(item =>
      item && typeof item.name === "string" && item.name.trim() !== "" &&
      typeof item.category === "string" && item.category.trim() !== ""
    )) {
      return { error: "بيانات المنتجات غير صالحة.", items: [] };
    }
    return { error: "", items: body.items };
  } catch {
    return { error: "تعذر قراءة JSON.", items: [] };
  }
}

function viewState({ loading, error, items }) {
  if (loading) return "loading";
  if (error) return "error";
  if (items.length === 0) return "empty";
  return "ready";
}

function filterItems(items, query, category) {
  const needle = query.trim().toLowerCase();
  return items.filter(item => {
    const matchesName = item.name.toLowerCase().includes(needle);
    const matchesCategory = category === "" || item.category === category;
    return matchesName && matchesCategory;
  });
}

const seed = [
  {
    "name": "دفتر A5",
    "category": "قرطاسية"
  },
  {
    "name": "قلم حبر",
    "category": "قرطاسية"
  },
  {
    "name": "كوب",
    "category": "أدوات"
  },
  {
    "name": "ملف A5",
    "category": "أدوات"
  }
];

function makeMock(mode, delay = 0) {
  return async function mockFetch(path) {
    if (delay > 0) await new Promise(resolve => setTimeout(resolve, delay));
    if (mode === "network") throw new Error("offline");
    if (path !== "/products.json" || mode === "http") {
      return { status: 404, ok: false };
    }
    const body = mode === "data" ? "{" : JSON.stringify({ items: mode === "empty" ? [] : seed });
    return { status: 200, ok: true, json: async () => JSON.parse(body) };
  };
}

function startPage() {
  const source = document.querySelector("#source");
  const query = document.querySelector("#query");
  const category = document.querySelector("#category");
  const button = document.querySelector("#load");
  const status = document.querySelector("#status");
  const list = document.querySelector("#items");
  let items = [];
  let loading = false;
  let error = "";

  function render() {
    const matches = filterItems(items, query.value, category.value);
    const state = viewState({ loading, error, items: matches });
    list.replaceChildren();
    if (state === "loading") status.textContent = "جارٍ تحميل المنتجات…";
    if (state === "error") status.textContent = error;
    if (state === "empty") {
      status.textContent = items.length === 0 ? "الكتالوج فارغ." : "لا توجد نتائج تطابق البحث.";
    }
    if (state === "ready") {
      status.textContent = "عدد النتائج: " + matches.length;
      for (const item of matches) {
        const row = document.createElement("li");
        row.textContent = item.name + " | " + item.category;
        list.append(row);
      }
    }
  }

  async function reload() {
    if (loading) return;
    const request = source.value === "file" ? fetch : makeMock(source.value, 500);
    loading = true;
    items = [];
    error = "";
    source.disabled = query.disabled = category.disabled = button.disabled = true;
    category.replaceChildren(new Option("كل الفئات", ""));
    render();

    const result = await loadCatalogue(request);
    items = result.items;
    error = result.error;
    for (const name of new Set(items.map(item => item.category))) {
      category.add(new Option(name, name));
    }
    loading = false;
    source.disabled = query.disabled = category.disabled = button.disabled = false;
    render();
  }

  query.addEventListener("input", render);
  category.addEventListener("change", render);
  button.addEventListener("click", reload);
  reload();
}

async function preview() {
  const sample = await loadCatalogue(makeMock("sample"));
  const matches = filterItems(sample.items, "a5", "قرطاسية");
  console.log(matches.map(item => item.name).join(","));
  const empty = await loadCatalogue(makeMock("empty"));
  console.log(viewState({ loading: false, ...empty }));
  const missing = await loadCatalogue(makeMock("http"));
  console.log(missing.error);
}

if (typeof document === "undefined") {
  preview();
} else {
  startPage();
}

