  if (mode === "http") return { ok: false, status: 503 };
  const body = mode === "data" ? "{" : JSON.stringify({ items });
  return { ok: true, status: 200, json: async () => JSON.parse(body) };
}

async function loadCatalogue(request) {
  let response;
  try {
    response = await request("/products.json");
  } catch {
    return { error: "تعذر الاتصال بالخادم.", items: [] };
  }
  if (!response.ok) {
    return { error: "خطأ HTTP (" + response.status + ").", items: [] };
  }
  try {
    const body = await response.json();
    if (!Array.isArray(body?.items) || !body.items.every(item =>
      item && typeof item.name === "string" && item.name.trim() !== "" &&
      typeof item.category === "string" && item.category.trim() !== ""
    )) {
      return { error: "بيانات المنتجات غير صالحة.", items: [] };
    }
    return { error: "", items: body.items };
  } catch {
    return { error: "تعذر قراءة JSON.", items: [] };
  }
}

function viewState({ loading, error, items }) {
  if (loading) return "loading";
  if (error) return "error";
  if (items.length === 0) return "empty";
  return "ready";
}

function filterItems(items, query, category) {
  const needle = query.trim().toLowerCase();
  return items.filter(item => {
    const matchesName = item.name.toLowerCase().includes(needle);
    const matchesCategory = category === "" || item.category === category;
    return matchesName && matchesCategory;
  });
}

async function report(request, query, category) {
  const result = await loadCatalogue(request);
  if (result.error) return "error";

  const matches = filterItems(result.items, query, category);
  const state = viewState({ loading: false, error: "", items: matches });
  if (state === "empty") return "empty";
  return "ready:" + JSON.stringify(matches.map(item => item.name));
}

